class Node:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def values(node):
    if node is None:
        return []
    return values(node.left) + [node.val] + values(node.right)

def slow(node):                    # brute force: compare each node with whole subtrees, O(N^2)
    if node is None:
        return True
    if any(v >= node.val for v in values(node.left)):
        return False
    if any(v <= node.val for v in values(node.right)):
        return False
    return slow(node.left) and slow(node.right)

def fast(node, lo=float('-inf'), hi=float('inf')):   # pass the allowed range down, O(N)
    if node is None:
        return True
    if not lo < node.val < hi:
        return False
    return fast(node.left, lo, node.val) and fast(node.right, node.val, hi)

good = Node(5, Node(3, Node(1), Node(4)), Node(8))
bad = Node(5, Node(3, Node(1), Node(6)), Node(8))      # 6 sits left of 5
for root in [good, bad, Node(2, Node(2))]:
    print(slow(root), fast(root))  # -> True True, then False False, then False False
